INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q700874', 'Battle of Bileća', 'The Battle of Bileća was fought in August 1388 between the forces of the Kingdom of Bosnia, led by Grand Duke Vlatko Vuković, and the Ottoman Empire under the leadership of Lala Shahin Pasha. The Ottoman army broke into Hum, the kingdom''s southern region.', 1388, 8, 26, NULL, NULL, NULL, 'day', '26 August 1388', 61, 'https://en.wikipedia.org/wiki/Battle_of_Bile%C4%87a'),
  ('Q7510113', 'Siege of Jajce', 'The siege of Jajce was a siege of the town of Jajce and its citadel in 1463, in a push by Ottomans to conquer as much of the Bosnian Kingdom, and continuation of the Ottoman–Hungarian Wars. After the fall of Travnik and royal fortress of Bobovac, in the initial days of invasion, Ottomans, led by the Sultan, captured the town.', 1463, NULL, NULL, 1463, 12, 25, 'year', '1463', 43, 'https://en.wikipedia.org/wiki/Siege_of_Jajce_(1463)'),
  ('Q121283166', 'Battle of Kljuc', 'The Battle of Kljuc was a pitched battle which took place during the conquest of Bosnia in 1463.', 1463, NULL, NULL, NULL, NULL, NULL, 'year', '1463', 37, 'https://en.wikipedia.org/wiki/Battle_of_Klju%C4%8D_(1463)'),
  ('Q20526199', 'Siege of Bihać', 'The city of Bihać in the Kingdom of Croatia within the Habsburg monarchy was besieged and captured by the Ottoman Empire in June 1592. With the arrival of Hasan-paša Predojević as the Beylerbey of the Bosnia Eyalet in 1591, a period of peace established between Emperor Rudolf II and Sultan Murad III ended and the provincial Ottoman armies launched an offensive on Croatia.', 1592, 6, 10, 1592, 6, 19, 'day', '10 June 1592 – 19 June 1592', 41, 'https://en.wikipedia.org/wiki/Siege_of_Biha%C4%87_(1592)'),
  ('Q4833104', 'Battle of Banja Luka', 'The Battle of Banja Luka (Turkish: Banaluka Muharebesi, Serbo-Croatian: Banjolučki boj) took place in Banja Luka, Ottoman Bosnia, on 4 August 1737, during the Austro-Russian-Turkish War. An Austrian army under Prince Joseph Hildberghausen was defeated, as it attempted to besiege the town, when it ran into a large Ottoman relief force led by Italian vizier Hekimoğlu Ali Pasha.', 1737, 8, 4, NULL, NULL, NULL, 'day', '4 August 1737', 43, 'https://en.wikipedia.org/wiki/Battle_of_Banja_Luka'),
  ('Q2258726', 'Herzegovina Uprising', 'The Herzegovina uprising (Serbian: Херцеговачки устанак, romanized: Hercegovački ustanak) was an uprising led by the Christian Serb population against the Ottoman Empire, firstly and predominantly in Herzegovina, from where it spread into Bosnia and Raška. It broke out in the summer of 1875, and in some regions lasted until the beginning of 1878.', 1875, NULL, NULL, 1878, NULL, NULL, 'year', '1875–1878', 64, 'https://en.wikipedia.org/wiki/Herzegovina_uprising_(1875%E2%80%931877)'),
  ('Q12019518', '1882 Herzegovina uprising', 'The 1882 Herzegovina uprising (Serbo-Croatian Latin: Hercegovački ustanak) was an uprising by Serbian and Bosniak populations in Bosnia and Herzegovina against Austro-Hungarian rule. It was preceded by the Herzegovina uprising of 1875–1877.', 1882, 1, 11, 1882, 4, NULL, 'day', '11 January 1882 – April 1882', 43, 'https://en.wikipedia.org/wiki/1882_Herzegovina_uprising'),
  ('Q3507323', 'Battle of Kupres', 'The Battle of Kupres (Croatian: Bitka za Kupres) was fought in 1942 during World War II in the Independent State of Croatia, between the forces of the Independent State of Croatia and the Yugoslav Partisans, in and around the town of Kupres in western Bosnia. The Partisans launched three concentrated attacks against the garrison of 1,500 men during the nights of 11/12 August, 14 August, and 19 August.', 1942, 7, 28, 1942, 8, 19, 'day', '28 July 1942 – 19 August 1942', 39, 'https://en.wikipedia.org/wiki/Battle_of_Kupres_(1942)'),
  ('Q1419973', 'Battle of the Sutjeska', 'Operation Schwarz (German: Unternehmen Schwarz), also known as the Fifth Enemy Offensive (Serbo-Croatian Latin: Peta neprijateljska ofanziva) in Yugoslav historiography and often identified with its final phase, the Battle of the Sutjeska (Serbo-Croatian Latin: Bitka na Sutjesci pronounced [bîtka na sûtjɛst͡si]) was a joint attack by the Axis. Taking place from 15 May to 16 June 1943, it aimed to destroy the main Yugoslav Partisan force, near the Sutjeska River in south-eastern Bosnia.', 1943, 5, 15, 1943, 6, 16, 'day', '15 May 1943 – 16 June 1943', 57, 'https://en.wikipedia.org/wiki/Operation_Schwarz'),
  ('Q127872674', 'Battle of Neretva', 'Operation Weiss (German: Unternehmen Weiß), also known as the Fourth Enemy Offensive (Serbo-Croatian: Četvrta neprijateljska ofenziva/ofanziva), was a major Axis offensive launched against the Yugoslav Partisans throughout occupied Yugoslavia during World War II. It was one of the most significant confrontations of World War II in Yugoslavia. The offensive took place in early 1943, between 20 January and mid-to-late March.', 1943, 2, NULL, 1943, 4, NULL, 'month', 'February 1943 – April 1943', 61, 'https://en.wikipedia.org/wiki/Operation_Weiss'),
  ('Q3501165', 'Battle of Odžak', 'The Battle of Odžak was the last battle of World War II in Europe. The battle began on 19 April 1945 and lasted until 25 May 1945, 17 days after the end of the war in Europe.', 1945, 4, 19, 1945, 5, 25, 'day', '19 April 1945 – 25 May 1945', 51, 'https://en.wikipedia.org/wiki/Battle_of_Od%C5%BEak'),
  ('Q11147774', 'Mostar Operation', 'The Mostar Operation was a series of Yugoslav Partisan military operations in Herzegovina from February 6–15, 1945.', 1945, NULL, NULL, 1945, 2, 15, 'year', '1945', 37, 'https://en.wikipedia.org/wiki/Mostar_operation'),
  ('Q13557465', 'Operation Sarajevo', 'The Sarajevo Operation was an operation by the Yugoslav Partisan Army which led to the liberation of Sarajevo and Central Bosnia in March-April 1945.', 1945, 3, 28, 1945, 4, 10, 'day', '28 March 1945 – 10 April 1945', 41, 'https://en.wikipedia.org/wiki/Sarajevo_Operation'),
  ('Q16826045', 'Cazin uprising', 'The Cazin rebellion (Serbo-Croatian: Cazinska buna, Цазинска буна) was an armed anti-state rebellion of peasants that occurred in May 1950 in the towns of Cazin and Velika Kladuša in the Bosanska Krajina region, as well as Slunj in Croatia, at that time part of Communist Yugoslavia. The peasants revolted against the forced collectivization and collective farms set up by the Yugoslav government following a drought in 1949, after which they had been punished due to their inability to meet the quotas.', 1950, 5, NULL, NULL, NULL, NULL, 'month', 'May 1950', 39, 'https://en.wikipedia.org/wiki/Cazin_rebellion'),
  ('Q11248850', '1969 Banja Luka earthquake', 'A series of earthquakes struck Banja Luka on October 26 and 27, 1969. They began with an unusually strong tremor on the night of October 26 at 02:55.', 1969, 10, 27, NULL, NULL, NULL, 'day', '27 October 1969', 45, 'https://en.wikipedia.org/wiki/1969_Banja_Luka_earthquake'),
  ('Q175653', 'Siege of Sarajevo', 'The Siege of Sarajevo (Serbian: Опсада Сарајева) (Croatian: Opsada Sarajeva) was a prolonged military blockade of Sarajevo, the capital of the Republic of Bosnia and Herzegovina, during the Bosnian War. Following Bosnia and Herzegovina''s declaration of independence, and amid escalating ethnic violence in the city, forces of the Yugoslav People''s Army (JNA) surrounded Sarajevo, establishing a complete military encirclement of the city.', 1990, NULL, NULL, 1996, 2, 29, 'decade', '1990s – 29 February 1996', 73, 'https://en.wikipedia.org/wiki/Siege_of_Sarajevo'),
  ('Q4947415', 'Bosnian Serb referendum, 1991', 'A referendum on remaining in Yugoslavia was held in the parts of Bosnia and Herzegovina with a significant Serb population on 10 November 1991. The referendum was organised by the Bosnian Serb Assembly and asked two questions; to Serbs it asked: Do you agree with the decision of Assembly of the Serbian people in Bosnia and Herzegovina of October 24, 1991, that the Serbian people should remain in a common Yugoslav state with Serbia, Montenegro, the SAO Krajina, SAO Slavonija, Baranja and Western Srem, and with others who have come out for remaining?', 1991, 11, 10, NULL, NULL, NULL, 'day', '10 November 1991', 39, 'https://en.wikipedia.org/wiki/1991_Bosnian_Serb_referendum'),
  ('Q751452', '1992 Yugoslav People''s Army column incident in Tuzla', 'The 1992 Yugoslav People''s Army column incident in Tuzla, also known as Tuzla column (Serbo-Croatian: Tuzlanska kolona, Тузланска колона) was an attack on the 92nd Motorized Brigade of the Yugoslav People''s Army (JNA) in the Bosnian city of Tuzla on 15 May 1992. The incident occurred at the road junction of Brčanska Malta.', 1992, 5, 15, NULL, NULL, NULL, 'day', '15 May 1992', 43, 'https://en.wikipedia.org/wiki/1992_Yugoslav_People''s_Army_column_incident_in_Tuzla'),
  ('Q3031484', 'Korićani Cliffs massacre', 'The Korićani Cliffs massacre was the mass murder of more than 200 Bosniak and Bosnian Croat men on 21 August 1992, during the Bosnian War, at the Korićani Cliffs on Mount Vlašić in central Bosnia and Herzegovina. The victims, former detainees from the Bosnian Serb-run concentration camp at Trnopolje, were separated out from a larger group of civilians being taken to Republic of Bosnia and Herzegovina-controlled territory in central Bosnia.', 1992, 8, 21, NULL, NULL, NULL, 'day', '21 August 1992', 45, 'https://en.wikipedia.org/wiki/Kori%C4%87ani_Cliffs_massacre'),
  ('Q3042255', 'Višegrad massacres', 'The Višegrad massacres were acts of mass murder committed against the Bosniak civilian population of the town and municipality of Višegrad during the ethnic cleansing of eastern Bosnia by Republika Srpska police and military forces during the spring and summer of 1992, at the start of the Bosnian War. According to documents of the International Criminal Tribunal for the former Yugoslavia (ICTY), based on the victims reports, some 3,000 Bosniaks were murdered during the violence in Višegrad and its surroundings, including some 600 women and 119 children.', 1992, NULL, NULL, NULL, NULL, NULL, 'year', '1992', 52, 'https://en.wikipedia.org/wiki/Vi%C5%A1egrad_massacres'),
  ('Q3268036', 'Foča massacres', 'There was a campaign of ethnic cleansing in the area of the town of Foča committed by Serb military, police, and paramilitary forces on Bosniak civilians from 7 April 1992 to January 1994 during the Bosnian War. By one estimate, around 21,000 non-Serbs left Foča after July 1992.', 1992, 4, 7, 1994, 1, NULL, 'day', '7 April 1992 – January 1994', 57, 'https://en.wikipedia.org/wiki/Fo%C4%8Da_ethnic_cleansing'),
  ('Q3268468', 'Prijedor massacre', 'During the Bosnian War, there was an ethnic cleansing campaign committed by the Bosnian Serb political and military leadership – Army of the Republika Srpska, mostly against Bosniak and Croat civilians in the Prijedor region of Bosnia and Herzegovina in 1992 and 1993. The composition of non-Serbs was drastically reduced: out of a population of 50,000 Bosniaks and 6,000 Croats, only some 6,000 Bosniaks and 3,000 Croats remained in the municipality by the end of the war.', 1992, NULL, NULL, NULL, NULL, NULL, 'year', '1992', 48, 'https://en.wikipedia.org/wiki/Prijedor_ethnic_cleansing'),
  ('Q3500162', 'Bijeljina massacre', 'The Bijeljina massacre involved the killing of civilians by Serb paramilitary groups in Bijeljina on 1–2 April 1992 in the run-up to the Bosnian War. The majority of those killed were Bosnian Muslims.', 1992, 4, 2, 1992, 4, 2, 'day', '2 April 1992', 48, 'https://en.wikipedia.org/wiki/Bijeljina_massacre'),
  ('Q3724348', 'Siege of Mostar', 'The siege of Mostar was fought during the Bosnian War first in 1992 and then again later in 1993 to 1994. Initially lasting between April 1992 and June 1992, it involved the Croatian Defence Council (HVO) and the Army of the Republic of Bosnia and Herzegovina (ARBiH) fighting against the Serb-dominated Yugoslav People''s Army (JNA) after Bosnia and Herzegovina declared its independence from Yugoslavia.', 1992, 4, NULL, 1993, 12, NULL, 'month', 'April 1992 – December 1993', 50, 'https://en.wikipedia.org/wiki/Siege_of_Mostar'),
  ('Q4122023', 'Siege of Bihać', 'The siege of Bihać was a three-year-long siege of the northwestern Bosnian town of Bihać by the Army of the Republika Srpska, the Army of the Republic of Serbian Krajina and Bosnian Muslim dissenters led by Fikret Abdić during the 1992–1995 Bosnian War. The siege lasted for three years, from June 1992 until 4–5 August 1995, when Operation Storm ended it after the Croatian Army (HV) overran the rebel Serbs in Croatia and northwest of the besieged town.', 1992, 6, 12, 1995, 8, 5, 'day', '12 June 1992 – 5 August 1995', 47, 'https://en.wikipedia.org/wiki/Siege_of_Biha%C4%87_(1992%E2%80%931995)'),
  ('Q4907325', 'Bikavac fire', 'The Bikavac fire refers to the arson perpetrated in Bikavac, near Višegrad, eastern Bosnia, on 27 June 1992 in which at least 60 Bosniak civilians, mostly women and children, were burned alive after the Serb forces forced them into a house which was then set on fire.', 1992, 6, 27, NULL, NULL, NULL, 'day', '27 June 1992', 37, 'https://en.wikipedia.org/wiki/Bikavac_fire'),
  ('Q5286645', 'Doboj massacre', 'The Doboj ethnic cleansing refers to war crimes, including murder, forced deportation, persecution and wanton destruction, committed against Bosniaks and Croats in the Doboj area by the Yugoslav People''s Army and Serb paramilitary units from May until September 1992 during the Bosnian war. On 26 September 1997, Serb soldier Nikola Jorgić was found guilty by the Düsseldorf Oberlandesgericht (Higher Regional Court) on 11 counts of genocide involving the murder of 30 persons in the Doboj region, making it the first Bosnian Genocide prosecution.', 1992, 4, NULL, 1992, 10, NULL, 'month', 'April 1992 – October 1992', 45, 'https://en.wikipedia.org/wiki/Doboj_ethnic_cleansing'),
  ('Q6471158', 'Ferhadija massacre', 'The Sarajevo bread line massacre refers to the artillery attack on Sarajevo on 27 May 1992, suspected to have been carried out by the Army of Republika Srpska. Three grenades were fired from the position in the direction of Borije, which exploded among civilians who were waiting in line for bread on Sarajevo''s main street Vaso Miskin street (today''s Ferhadija street).', 1992, 5, 27, NULL, NULL, NULL, 'day', '27 May 1992', 37, 'https://en.wikipedia.org/wiki/Sarajevo_bread_line_massacre'),
  ('Q8075596', 'Zvornik massacre', 'The Zvornik massacre refers to acts of mass murder and violence committed against Bosniaks and other non-Serb civilians in Zvornik by Serb paramilitary groups (Arkanovci, Territorial Defence units, White Eagles, Yellow Wasps) at the beginning of the Bosnian War in 1992. It was part of a wider campaign of ethnic cleansing in the Bosnian War: by one estimate, 40,000 Bosniaks were expelled from the Zvornik district.', 1992, 7, NULL, 1992, 7, NULL, 'month', 'July 1992', 43, 'https://en.wikipedia.org/wiki/Zvornik_massacre'),
  ('Q12627990', 'Battle of Kupres', 'The Battle of Kupres (Serbo-Croatian: Bitka za Kupres / Битка за Купрес) was a battle of the Bosnian War, fought between the Bosnian Croat Croatian Defence Forces (Hrvatske obrambene snage - HOS) supported by the Croatian Army (Hrvatska vojska – HV) troops on one side and the Yugoslav People''s Army (Jugoslovenska narodna armija – JNA), augmented by the Bosnian Serb Territorial Defense Force, on the other. The battle took place at the Kupres Plateau from 3–11 April 1992.', 1992, 4, 3, 1992, 4, 11, 'day', '3 April 1992 – 11 April 1992', 41, 'https://en.wikipedia.org/wiki/Battle_of_Kupres_(1992)'),
  ('Q25387520', 'Kazani pit killings', 'During the Siege of Sarajevo in the Bosnian War, a number of predominantly ethnic Serbs living inside besieged Sarajevo were murdered by the forces of Mušan Topalović, commander of the 10th Mountain Brigade in the Army of the Republic of Bosnia and Herzegovina, and disposed of in the Kazani pit mass grave.', 1992, NULL, NULL, NULL, NULL, NULL, 'year', '1992', 48, 'https://en.wikipedia.org/wiki/Kazani_pit_killings'),
  ('Q30687544', 'Siege of Goražde', 'The siege of Goražde (Bosnian: Opsada Goražda; Serbian Cyrillic: Опсада Горажда) refers to engagements during the Bosnian War (1992–95) in and around the town of Goražde in eastern Bosnia. On 4 May 1992, Goražde was besieged by the Army of Republika Srpska (VRS).', 1992, 4, 1, 1995, 10, 1, 'day', '1 April 1992 – 1 October 1995', 41, 'https://en.wikipedia.org/wiki/Siege_of_Gora%C5%BEde'),
  ('Q1379845', 'Kravica attack', 'The Kravica attack was an attack on the Bosnian Serb village of Kravica by the Army of the Republic of Bosnia and Herzegovina (ARBiH) from the Srebrenica enclave on Orthodox Christmas Day, 7 January 1993. The attack was organized to coincide with the Serbian Orthodox Christmas, leaving the Serbs unprepared for any attack.', 1993, 1, 7, NULL, NULL, NULL, 'day', '7 January 1993', 47, 'https://en.wikipedia.org/wiki/Kravica_attack_(1993)'),
  ('Q1387922', 'Ahmići massacre', 'The Ahmići massacre was the mass murder of approximately 120 Bosniak civilians by members of the Croatian Defence Council in April 1993, during the Croat–Muslim War. The massacre was the culmination of the Lašva Valley ethnic cleansing committed by the political and military leadership of the Croatian Community of Herzeg-Bosnia.', 1993, 4, 16, NULL, NULL, NULL, 'day', '16 April 1993', 51, 'https://en.wikipedia.org/wiki/Ahmi%C4%87i_massacre'),
  ('Q1907384', 'Massacre in Grabovica', 'The Grabovica massacre refers to the murders of at least 13 ethnic Croat inhabitants of the village of Grabovica near Jablanica by members of the Army of the Republic of Bosnia and Herzegovina (ARBiH) 9th Brigade and other unidentified members of ARBiH on 8 or 9 September 1993. The International Court Tribunal for former Yugoslavia concluded that the number of victims totaled 13, lower than the alleged number of 33, however other sources still maintain this higher figure.', 1993, 9, 8, 1993, 9, 9, 'day', '8 September 1993 – 9 September 1993', 43, 'https://en.wikipedia.org/wiki/Grabovica_massacre'),
  ('Q2504602', 'Lašva Valley ethnic cleansing', 'The Lašva Valley ethnic cleansing, also known as the Lašva Valley case, refers to numerous war crimes committed during the Bosnian War by the Croatian Community of Herzeg-Bosnia''s political and military leadership on Bosniak civilians in the Lašva Valley region of Bosnia-Herzegovina. The campaign, planned from May 1992 to March 1993 and erupting the following April, was meant to implement objectives set forth by Croat nationalists in November 1991.', 1993, 4, NULL, 1993, 4, NULL, 'month', 'April 1993', 50, 'https://en.wikipedia.org/wiki/La%C5%A1va_Valley_ethnic_cleansing'),
  ('Q3503418', 'Križančevo selo massacre', 'On 22 December 1993, after an attack by the Army of the Republic of Bosnia and Herzegovina (ARBiH) on Croatian Defence Council (HVO) positions in Križančevo selo, a hamlet in the Lašva Valley in central Bosnia, at least 14 Croat soldiers and civilians were killed.', 1993, 12, 22, NULL, NULL, NULL, 'day', '22 December 1993', 41, 'https://en.wikipedia.org/wiki/Kri%C5%BEan%C4%8Devo_selo_massacre'),
  ('Q4588836', 'Trusina massacre', 'The Trusina massacre occurred on 16 April 1993 in the village of Trusina, located in the municipality of Konjic in Bosnia and Herzegovina, where 22 people, six Croat prisoners of war and 16 Croat civilians, were killed by the Army of the Republic of Bosnia and Herzegovina (ARBiH) during the Croat–Bosniak War.', 1993, 4, 16, NULL, NULL, NULL, 'day', '16 April 1993', 37, 'https://en.wikipedia.org/wiki/Trusina_massacre'),
  ('Q5286741', 'Dobrinja mortar attack', 'The Dobrinja mortar attack was a massacre which occurred at 10:20 a.m. on 1 June 1993, in Dobrinja, a suburb west of Sarajevo in Bosnia and Herzegovina.', 1993, 6, 1, 1995, 6, 21, 'day', '1 June 1993 – 21 June 1995', 37, 'https://en.wikipedia.org/wiki/Dobrinja_mortar_attack'),
  ('Q6393896', 'Štrpci massacre', 'The Štrpci massacre (Bosnian: Masakr u Štrpcima) was the massacre of 19 civilians (18 Bosniaks and one Croat) on 27 February 1993, taken from a Belgrade-Bar train at Štrpci railway station near Višegrad, on Bosnian territory. Members of the Serbian Avengers (Osvetnici) paramilitary unit, commanded by Milan Lukić, were responsible for the abductions and subsequent massacre.', 1993, 2, 27, NULL, NULL, NULL, 'day', '27 February 1993', 48, 'https://en.wikipedia.org/wiki/%C5%A0trpci_massacre'),
  ('Q7582417', '12 April 1993 Srebrenica shelling', 'On 12 April 1993, the Army of Republika Srpska (VRS) launched an artillery attack against the town of Srebrenica. The attack left 56 dead (including 14 children killed on a school playground), and 73 seriously wounded.', 1993, 4, 12, NULL, NULL, NULL, 'day', '12 April 1993', 37, 'https://en.wikipedia.org/wiki/12_April_1993_Srebrenica_shelling'),
  ('Q7628907', 'Stupni Do massacre', 'The Stupni Do massacre was a massacre committed by Croatian forces on Bosniak civilians during the Croat–Bosniak war in the village of Stupni Do in Vareš municipality. It was committed on 23 October 1993 by Croatian Defence Council (HVO) units called "Apostoli" and "Maturice" led by Ivica Rajić, who pleaded guilty before ICTY for war crimes in October 2005.', 1993, 10, 23, NULL, NULL, NULL, 'day', '23 October 1993', 41, 'https://en.wikipedia.org/wiki/Stupni_Do_massacre'),
  ('Q61861980', 'Battle of Bugojno', 'The Battle of Bugojno (Bosnian and Croatian: Bitka za Bugojno) was fought between forces of the Army of the Republic of Bosnia and Herzegovina (ARBiH) and the Croatian Defence Council (HVO) for control of the town and municipality of Bugojno in central Bosnia, from 18–28 July 1993. The area of Bugojno was under joint control of the ARBiH 307th Brigade and the HVO Eugen Kvaternik Brigade since the start of the Bosnian War.', 1993, 7, 29, NULL, NULL, NULL, 'day', '29 July 1993', 37, 'https://en.wikipedia.org/wiki/Battle_of_Bugojno'),
  ('Q568992', 'Operation Bøllebank', 'Operation Bøllebank (English: Operation Bully Bashing) was a military confrontation between Bosnian Serb military forces and Danish, Norwegian, and Swedish combat units composing the United Nations Protection Force''s (UNPROFOR) Nordic Battalion (NORDBAT 2), outside of the city of Tuzla on 29 April 1994. When trying to relieve Swedish forces at the Tango 2 observation post past the village of Kalesija, Danish forces of the Jydske Dragonregiment were ambushed by the Bosnian Serb Šekovići brigade.', 1994, 4, 29, NULL, NULL, NULL, 'day', '29 April 1994', 47, 'https://en.wikipedia.org/wiki/Operation_B%C3%B8llebank'),
  ('Q1482369', 'Markale massacres', 'The Markale massacres were two bombardments, with at least one of them confirmed to have been carried out by the Army of Republika Srpska, targeting civilians at the Markale (marketplace) during the siege of Sarajevo in the Bosnian War. The first occurred on 5 February 1994; 68 people were killed and 144 more were wounded by a 120-millimetre (4.7 in) mortar.', 1994, 2, 5, NULL, NULL, NULL, 'day', '5 February 1994', 58, 'https://en.wikipedia.org/wiki/Markale_massacres'),
  ('Q4505468', 'Battle of Kupres', 'The Battle of Kupres (Bosnian, Croatian and Serbian: Bitka za Kupres) was a battle of the Bosnian War, fought between the Army of the Republic of Bosnia and Herzegovina (ARBiH) and the Croatian Defence Council (HVO) on one side and the Army of Republika Srpska (VRS) on the other from 20 October to 3 November 1994. It marks the first tangible evidence of the Bosniak–Croat alliance set out in the Washington Agreement of March 1994, brokered by the United States to end the Croat–Bosniak War fought between the ARBiH and the HVO in Bosnia and Herzegovina.', 1994, 10, 20, 1994, 11, 3, 'day', '20 October 1994 – 3 November 1994', 37, 'https://en.wikipedia.org/wiki/Battle_of_Kupres_(1994)'),
  ('Q170334', 'Srebrenica massacre', 'The Srebrenica massacre, also known as the Srebrenica genocide, was the July 1995 genocidal killing of more than 8,000 Bosniak men and boys in and around the town of Srebrenica during the Bosnian War. It was mainly perpetrated by units of the Bosnian Serb Army of Republika Srpska under Ratko Mladić, though the Serb paramilitary unit Scorpions also participated.', 1995, 7, NULL, 1995, 7, 22, 'month', 'July 1995 – 22 July 1995', 82, 'https://en.wikipedia.org/wiki/Srebrenica_massacre'),
  ('Q769377', 'Operation Storm', 'Operation Storm (Serbo-Croatian: Operacija Oluja / Операција Олуја) in August 1995 was the last major battle of the Croatian War of Independence and a major factor in the outcome of the Bosnian War. It was a decisive victory for the Croatian Army (HV), which attacked across a 630-kilometre (390 mi) front against the self-declared proto-state Republic of Serbian Krajina (RSK), and a strategic victory for the Army of the Republic of Bosnia and Herzegovina (ARBiH).', 1995, 8, 4, 1995, 8, 7, 'day', '4 August 1995 – 7 August 1995', 69, 'https://en.wikipedia.org/wiki/Operation_Storm'),
  ('Q1756737', 'Operation Mistral 2', 'Operation Mistral 2, officially codenamed Operation Maestral 2, was a Croatian Army (HV) and Croatian Defence Council (HVO) offensive in western Bosnia and Herzegovina on 8–15 September 1995 as part of the Bosnian War. Its objective was to create a security buffer between Croatia and positions held by the Bosnian Serb Army of Republika Srpska (VRS).', 1995, 9, 8, 1995, 9, 15, 'day', '8 September 1995 – 15 September 1995', 45, 'https://en.wikipedia.org/wiki/Operation_Mistral_2'),
  ('Q2097350', 'Tuzla massacre', 'On 25 May 1995, the Army of Republika Srpska (VRS) launched an artillery attack against the town of Tuzla as part of the Bosnian War, which left 71 civilians dead and another 240 wounded. The event is also known as the Tuzla massacre.', 1995, 5, 25, NULL, NULL, NULL, 'day', '25 May 1995', 51, 'https://en.wikipedia.org/wiki/25_May_1995_Tuzla_massacre'),
  ('Q3480288', 'Fall of Srebrenica and Žepa', 'The siege of Srebrenica (Serbo-Croatian: Opsada Srebrenice, Опсада Сребреницe) was a three-year siege of the town of Srebrenica in eastern Bosnia and Herzegovina which lasted from April 1992 to July 1995 during the Bosnian War. Initially assaulted by the Yugoslav People''s Army (JNA) and the Serbian Volunteer Guard (SDG), the town was encircled by the Army of Republika Srpska (VRS) in May 1992, starting a brutal siege which was to last for the majority of the Bosnian War.', 1995, 5, 9, 1995, 7, 11, 'day', '9 May 1995 – 11 July 1995', 47, 'https://en.wikipedia.org/wiki/Siege_of_Srebrenica'),
  ('Q3540932', 'Split Agreement', 'The Split Agreement or Split Declaration (Serbo-Croatian: Splitski sporazum or Splitska deklaracija) was a mutual defence agreement between Croatia, the Republic of Bosnia and Herzegovina and the Federation of Bosnia and Herzegovina, signed in Split, Croatia on 22 July 1995. It called on the Croatian Army (HV) to intervene militarily in Bosnia and Herzegovina, primarily in relieving the siege of Bihać.', 1995, 7, 22, NULL, NULL, NULL, 'day', '22 July 1995', 47, 'https://en.wikipedia.org/wiki/Split_Agreement'),
  ('Q4872697', 'Battle of Vrbanja Bridge', 'The Battle of Vrbanja Bridge ([ʋr̩baɲa], wer-bahn-yah) was an armed confrontation which took place on 27 May 1995, between United Nations (UN) peacekeepers from the French Army and elements of the Bosnian Serb Army of Republika Srpska (VRS). The fighting occurred at the Vrbanja Bridge crossing of the Miljacka river in Sarajevo, Bosnia and Herzegovina, during the Bosnian War.', 1995, 5, 27, NULL, NULL, NULL, 'day', '27 May 1995', 39, 'https://en.wikipedia.org/wiki/Battle_of_Vrbanja_Bridge'),
  ('Q16113803', 'Battle of Vozuća', 'The Battle of Vozuća was a military offensive fought during the final months of the Bosnian War between the Army of the Republic of Bosnia and Herzegovina (ARBiH) and the Army of Republika Srpska (VRS) in the Vozuća–Ozren area. On 10 September 1995, units of the ARBiH 2nd and 3rd Corps launched a combined offensive against VRS positions.', 1995, 5, 27, 1995, 9, 10, 'day', '27 May 1995 – 10 September 1995', 43, 'https://en.wikipedia.org/wiki/Battle_of_Vozu%C4%87a'),
  ('Q16879871', '2014 Southeast Europe floods', 'Between 13 and 18 May 2014 a low-pressure cyclone designated Tamara and Yvette affected a large area of Southeastern and Central Europe, causing floods and landslides. Serbia and Bosnia and Herzegovina suffered the greatest damage, as the rain was the heaviest in 120 years of recorded weather measurements.', 2014, 5, 27, 2014, 5, 27, 'day', '27 May 2014', 63, 'https://en.wikipedia.org/wiki/2014_Southeast_Europe_floods'),
  ('Q27019722', 'Republika Srpska National Day referendum, 2016', 'A referendum on the National Day of Republika Srpska, called the Day of Republika Srpska (Serbo-Croatian: Dan Republike Srpske or Dan RS; Дан Републике Српске or Дан РС) was held on 25 September 2016. The Constitutional Court of Bosnia and Herzegovina had on 26 November 2015 ruled against the constitutionality of the holiday, deeming it discriminatory against non-Serbs in the entity.', 2016, 9, 25, NULL, NULL, NULL, 'day', '25 September 2016', 41, 'https://en.wikipedia.org/wiki/2016_Republika_Srpska_National_Day_referendum'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q109416875', '2021 floods in Bosnia and Herzegovina', 'Between 4 and 11 November 2021, heavy rainfall resulted in widespread flash flooding in many places across Bosnia and Herzegovina. The Federal Hydrometereological Institute issued a red warning on 5 November 2021 for flooding.', 2021, NULL, NULL, 2021, 11, 11, 'year', '2021', 37, 'https://en.wikipedia.org/wiki/2021_Bosnia_and_Herzegovina_floods'),
  ('Q130425716', '2024 Bosnia and Herzegovina floods', 'During the night of 3–4 October 2024, central and southern Bosnia and Herzegovina experienced severe flooding, the worst since the 2014 Southeast Europe floods, due to an atmospheric river formed over the Adriatic Sea. Several central towns were flooded, and numerous towns and villages became inaccessible as roads, bridges, and railways were obstructed by floodwaters and landslides.', 2024, 10, 3, 2024, 10, 4, 'day', '3 October 2024 – 4 October 2024', 45, 'https://en.wikipedia.org/wiki/2024_Bosnia_and_Herzegovina_floods');
